from hashlib import sha256
from pathlib import Path

from virvision.perception.base import ModelArtifact


def artifact(path: Path) -> ModelArtifact:
    digest = sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(block)
    return ModelArtifact(path.resolve(), path.stat().st_size, digest.hexdigest())
